#include <iostream>
#include <windows.h>
#include <cstdlib>
#include <ctime>
#include <cmath>

long double f(long double x) {
    return sin(x);
}

long double integrateRect(long double a, long double b, long double n) {
    long double h = (b - a) / n;
    long double s = 0;
    for (long int i = 0; i < n; i++) {
        s += f(a + i * h);
    }
    return s * h;
}

long double integrateTrap(long double a, long double b, long double n) {
    long double h = (b - a) / n;
    long double s = f(a) + f(b);
    for (long int i = 1; i < n; i++) {
        s += 2 * f(a + i * h);
    }
    return s * h / 2;
}

long double integrateSimpson(long double a, long double b, long double n) {
    long double h = (b - a) / n;
    long double s = f(a) + f(b);
    for (long int i = 1; i < n; i++) {
        if (i % 2 == 0) {
            s += 2 * f(a + i * h);
        } else {
            s += 4 * f(a + i * h);
        }
    }
    return s * h / 3;
}

