    const long int n = 100;
    const long int numThreads = 4;

    HANDLE hMutex = CreateMutex(NULL, FALSE, NULL);
    HANDLE hSemaphore = CreateSemaphore(NULL, 0, numThreads, NULL);
    HANDLE threads[numThreads];

    long double valueRect = 0, valueTrap = 0, valueSimpson = 0;

    for (long int i = 0; i < numThreads; i++) {
        threads[i] = CreateThread(NULL, 0, calculateThread, &valueRect, 0, NULL);
        Sleep(100); // для иллюстрации работы потоков
    }

    WaitForMultipleObjects(numThreads, threads, TRUE, INFINITE);

    ReleaseMutex(hMutex);
    CloseHandle(hMutex);
    CloseHandle(hSemaphore);
    for (long int i = 0; i < numThreads; i++) {
        CloseHandle(threads[i]);
