```
import math

class ChessPlayer:
    def __init__(self, name):
        self.name = name
        self.rating = 1200

class Tournament:
    def __init__(self):
        self.players = []

    def add_player(self, player):
        self.players.append(player)

    def simulate_match(self, player1, player2):
        rating1 = player1.rating
        rating2 = player2.rating

        result1 = 1 if math.exp((rating2 - rating1) / 400) < 1.4 else 0
        result2 = 1 - result1

        k = 32

        player1.rating = rating1 + k * (result1 - (1 if rating1 > 1200 else (1 - 1 / 1200)))
        player2.rating = rating2 + k * (result2 - (1 if rating2 > 1200 else (1 - 1 / 1200)))

    def print_scores(self):
        for player in self.players:
            print(f"{player.name} - Elo rating: {player.rating:.2f}")

def main():
    tournament = Tournament()

    while True:
        name = input("Enter player's name (or 'done' if all players entered): ")
        if name.lower() == 'done':
            break
        tournament.add_player(ChessPlayer(name))

    while len(tournament.players) > 1:
        while True:
            p1_name = input("Enter player 1's name: ")
            p2_name = input("Enter player 2's name: ")
            p1 = None
            p2 = None
            for player in tournament.players:
                if player.name == p1_name:
                    p1 = player
                elif player.name == p2_name:
                    p2 = player
            if p1 and p2:
                break
            print("Players not found. Please enter valid players names.")
        tournament.simulate_match(p1, p2)
        tournament.players.remove(p1)
        tournament.players.remove(p2)

    tournament.print_scores()

if __name__ == "__main__":
    main()
```

